{"code": "import random

def simulate_trial(N=3, verbose=True):
    """Simulate a single trial of the game with N balls."""
    # Initialize platform with balls 1 to N
    platform = list(range(1, N + 1))
    ramp = []

    if verbose:
        print(f"Initial platform: {platform}, ramp: {ramp}")

    step = 1

    while len(platform) > 0:
        # Randomly choose a piston position (1-indexed)
        piston_pos = random.randint(1, N)

        # Find which ball is at the piston position
        ball_at_piston = None
        if piston_pos in platform:
            ball_at_piston = piston_pos

        # Handle the ball ejection
        if ball_at_piston is not None:
            # This ball is ejected
            ejected_ball = ball_at_piston
            platform.remove(ejected_ball)

            # Check if any ball should be released from ramp
            released_ball = None
            if len(ramp) > 0 and ramp[0] < ejected_ball:
                released_ball = ramp.pop(0)

            # Update platform with released ball
            if released_ball is not None:
                platform.append(released_ball)
                platform.sort()  # Keep platform sorted

            if verbose:
                print(f"Step {step}: piston hits position {piston_pos}; ball {ejected_ball} ejected;", end=" ")
                if released_ball is not None:
                    print(f"ball {released_ball} released;", end=" ")
                else:
                    print("no ball released;", end=" ")
                print(f"new platform: {platform}, ramp: {ramp}")
        else:
            # No ball at piston position
            # Find which ball is on the ramp
            if piston_pos > 0:
                ramp.append(piston_pos)
                ramp.sort()  # Keep ramp sorted

                if verbose:
                    print(f"Step {step}: piston hits position {piston_pos}; no ball ejected;", end=" ")
                    print(f"ball {piston_pos} added to ramp; new platform: {platform}, ramp: {ramp}")
            else:
                if verbose:
                    print(f"Step {step}: piston hits position {piston_pos}; no ball at position;")

        step += 1

    if verbose:
        print(f"Game completed in {step-1} steps.")

    return step-1, platform, ramp

# Run 5 trials
print("Running 5 trials for N=3 balls:")
print("=" * 50)

for trial in range(1, 6):
    print(f"\nTrial {trial}:")
    print("-" * 30)
    steps, final_platform, final_ramp = simulate_trial(N=3, verbose=True)
    print(f"Final state: platform: {final_platform}, ramp: {final_ramp}")"}

